corrected_code:
const express = require('express');
const OpenApiValidator = require('express-openapi-validator');
const path = require('path');
const { Contract } = require('../models/contracts');

const app = express();
app.use(express.json());

app.use(
  OpenApiValidator.middleware({
    apiSpec: path.join(__dirname, 'specs', 'contracts-v3.json'),
    validateRequests: true
  })
);

app.post('/api/v3/contracts/:contractId/sign', async (req, res) => {
  if (!req.user || !req.user.email) {
    return res.status(401).json({ error: 'Signatory authentication required' });
  }

  const { signatureHash, signedAt } = req.body;

  const contract = await Contract.findById(req.params.contractId);
  if (!contract) {
    return res.status(404).json({ error: 'Contract not found' });
  }

  // Verify that the caller's email matches a pending signatory on this contract
  const signatory = contract.pendingSignatories.find(s => s.email === req.user.email);
  if (!signatory) {
    return res.status(403).json({ error: 'Access denied: caller is not an authorized signatory' });
  }

  contract.signatures.push({
    signatoryId: signatory.id,
    signerEmail: req.user.email,
    hash: signatureHash,
    timestamp: signedAt,
    status: 'EXECUTED'
  });
  await contract.save();

  res.status(200).json({ message: 'Contract successfully signed', contractId: contract.id });
});

app.listen(5003);
